solution.grep.zig:
const std = @import("std");

const Flags = struct { numbers: bool = false, names: bool = false, ignore_case: bool = false, invert: bool = false, entire: bool = false };
fn matches(line: []const u8, pattern: []const u8, flags: Flags) bool {
    var found = false;
    if (flags.entire) found = if (flags.ignore_case) std.ascii.eqlIgnoreCase(line, pattern) else std.mem.eql(u8, line, pattern) else if (pattern.len <= line.len) {
        for (0..line.len - pattern.len + 1) |i| {
            const part = line[i .. i + pattern.len];
            if (if (flags.ignore_case) std.ascii.eqlIgnoreCase(part, pattern) else std.mem.eql(u8, part, pattern)) {
                found = true;
                break;
            }
        }
    }
    return found != flags.invert;
}
pub fn grep(allocator: std.mem.Allocator, io: std.Io, dir: std.Io.Dir, pattern: []const u8, flag_text: []const u8, files: []const []const u8) ![]u8 {
    var flags: Flags = .{};
    var flag_tokens = std.mem.tokenizeAny(u8, flag_text, " \t");
    while (flag_tokens.next()) |flag| {
        if (std.mem.eql(u8, flag, "-n")) flags.numbers = true else if (std.mem.eql(u8, flag, "-l")) flags.names = true else if (std.mem.eql(u8, flag, "-i")) flags.ignore_case = true else if (std.mem.eql(u8, flag, "-v")) flags.invert = true else if (std.mem.eql(u8, flag, "-x")) flags.entire = true else return error.InvalidFlag;
    }
    var out = std.array_list.Managed(u8).init(allocator);
    errdefer out.deinit();
    for (files) |filename| {
        const text = try dir.readFileAlloc(io, filename, allocator, .unlimited);
        defer allocator.free(text);
        var offset: usize = 0;
        var number: usize = 0;
        while (offset < text.len) {
            const begin = offset;
            const newline = std.mem.indexOfScalarPos(u8, text, offset, '\n');
            const end = newline orelse text.len;
            offset = if (newline != null) end + 1 else end;
            number += 1;
            var line = text[begin..end];
            if (line.len > 0 and line[line.len - 1] == '\r') line = line[0 .. line.len - 1];
            if (!matches(line, pattern, flags)) continue;
            if (flags.names) {
                try out.appendSlice(filename);
                try out.append('\n');
                break;
            }
            if (files.len > 1) {
                try out.appendSlice(filename);
                try out.append(':');
            }
            if (flags.numbers) {
                const prefix = try std.fmt.allocPrint(allocator, "{d}:", .{number});
                defer allocator.free(prefix);
                try out.appendSlice(prefix);
            }
            try out.appendSlice(text[begin..offset]);
        }
    }
    return out.toOwnedSlice();
}

